mapper.update:
update jewelry_staff set real_name=#{realName}, phone=#{phone}, status=#{status},
  joined_date=#{joinedDate}, update_by=#{updateBy}, update_time=sysdate(), remark=#{remark}
where staff_id=#{staffId}

mapper.select:
select supplier_id supplierId,supplier_code supplierCode,supplier_name supplierName,
  status,remark
from jewelry_supplier where supplier_id=#{supplierId}

select t.transaction_id transactionId,t.document_id documentId,d.doc_no docNo,t.product_id productId, p.sku,p.product_name productName,t.transaction_type transactionType,t.on_hand_change onHandChange, t.reserved_change reservedChange,t.inspection_change inspectionChange,t.defect_change defectChange, t.before_on_hand beforeOnHand,t.after_on_hand afterOnHand,t.before_avg_cost beforeAvgCost, t.after_avg_cost afterAvgCost,t.operator_name operatorName,t.create_time createTime from jewelry_stock_transaction t join jewelry_document d on d.document_id=t.document_id join jewelry_product p on p.product_id=t.product_id
and t.product_id=#{productId}
order by t.transaction_id desc

select d.*,src.doc_type source_doc_type
from jewelry_document d
left join jewelry_document src on src.document_id=d.source_document_id

    and d.doc_no like concat('%',#{docNo},'%')
    and d.doc_type=#{docType}

        and d.status in ('PENDING_FIRST','PENDING_SECOND')
        and d.status=#{status}

    and d.creator_user_id=#{creatorUserId}

order by d.document_id desc

select count(*) from jewelry_document
where doc_type='CUSTOMER_RETURN' and source_document_id=#{sourceDocumentId}
  and status in ('PENDING_FIRST','PENDING_SECOND','POSTED')

mapper.update:
update jewelry_stock set inspection_reserved_qty=inspection_reserved_qty+#{qty},version=version+1,
  update_time=sysdate()
where product_id=#{productId} and inspection_qty-inspection_reserved_qty>=#{qty}

update jewelry_stock set inspection_reserved_qty=inspection_reserved_qty-#{qty},version=version+1,
  update_time=sysdate()
where product_id=#{productId} and inspection_reserved_qty>=#{qty}

update jewelry_stock set defect_reserved_qty=defect_reserved_qty+#{qty},version=version+1,
  update_time=sysdate()
where product_id=#{productId} and defect_qty-defect_reserved_qty>=#{qty}

update jewelry_stock set defect_reserved_qty=defect_reserved_qty-#{qty},version=version+1,
  update_time=sysdate()
where product_id=#{productId} and defect_reserved_qty>=#{qty}
